Item.method_code:
let maxCheck = 30;
function disableTabs() {
	if (!(parent.document.frames && parent.document.frames.relationships) || !parent.document.frames.relationships.currTabID) {
		if (--maxCheck === 0) { return; }
		setTimeout(disableTabs, 50);
		return;
	}

	if (!document.item) {
		return;
	}
	const identityId = aras.getItemProperty(document.item, 'identity_id');
	const identityNode = aras.getItemById('Identity', identityId);
	const identityName = aras.getItemProperty(identityNode, 'name');

	let allowedType = 2; // User
	if (identityName == 'World') {
		allowedType = 1; // Site
	}

	const appl = parent.relationships.relTabbar;

	const qry = aras.newQryItem('PreferenceTypes');
	qry.setLevels(1);
	let res = qry.execute();
	if (!res) {
		return;
	}

	const prefTabTypes = res.selectNodes('//Item[@type=\'PreferenceTabTypes\']');

	for (let i = 0; i < prefTabTypes.length; i++) {
		const prefTabType = prefTabTypes[i];

		let prefType = aras.getItemProperty(prefTabType, 'preference_tab_type');
		const prefITName = aras.getItemProperty(prefTabType, 'preference_tab');

		prefType = parseInt(prefType);
		if (isNaN(prefType) || prefType > 3 || prefType < 1) {
			prefType = 3;
		}

		if ((prefType & allowedType) === 0) {
			const xml = '' +
			'<Item type=\'RelationshipType\' action=\'get\' select=\'label\'>' +
				'<relationship_id>' +
					'<Item type=\'ItemType\' select=\'id\'>' +
						'<name>' + prefITName + '</name>' +
					'</Item>' +
				'</relationship_id>' +
			'</Item>';
			res = aras.applyItem(xml);
			if (typeof (res) != 'string' && res !== '') {
				continue;
			}
			const tmpDom = aras.createXMLDocument();
			tmpDom.loadXML(res);
			const labelNode = tmpDom.selectSingleNode('//label');
			if (!labelNode) {
				continue;
			}
			appl.removeTabByLabel(labelNode.text);
		}
	}

}

disableTabs();
